import sys


def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    home = lines[0].split("=")[1].strip()
    labels = []
    for raw in lines[1:]:
        if not raw.strip():
            continue
        fields = raw.split(";")
        title, first, last, street, postcode, city, country = (
            [f.strip() for f in fields[:7]]
        )

        name_line = " ".join(
            [f for f in [title, first, last] if f] or ["To the occupant"]
        )
        labels.append([name_line, street, f"{postcode} {city}" if postcode or city else "", country.upper()])

    if not labels:
        return

    for label in labels:
        for line in label:
            if line:
                print(line)
        print("---")


if __name__ == "__main__":
    main()
